import React, { useState, useEffect, useContext } from 'react';
import { Link } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';
import { API_URL } from '../config';

const PaymentModal = ({ course, onClose }) => {
  const [methods, setMethods] = useState([]);
  const [method, setMethod] = useState('');
  const [processing, setProcessing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');
  const [receipt, setReceipt] = useState(null);
  const { token, isAuthenticated, user } = useContext(AuthContext);

  useEffect(() => {
    fetch(`${API_URL}/payment-methods/`)
      .then(res => res.json())
      .then(setMethods)
      .catch(() => setMethods([]));
  }, []);

  if (!course) return null;

  const handlePayment = async (e) => {
    e.preventDefault();
    setProcessing(true);
    setError('');

    try {
      const res = await fetch(`${API_URL}/payments/simulate`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ course_id: course.id, method: method.toLowerCase() }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.detail || 'Le paiement a échoué.');
      }

      const selectedMethod = methods.find(m => m.key === method.toLowerCase());
      setReceipt({
        course: course.title,
        price: course.is_free ? 'Gratuit' : `${course.price.toLocaleString()} FCFA`,
        method: selectedMethod?.display_name || method,
        date: new Date().toLocaleDateString('fr-FR', { day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' }),
      });
      setSuccess(true);
    } catch (err) {
      setError(err.message);
    } finally {
      setProcessing(false);
    }
  };

  const sendReceiptByEmail = () => {
    const subject = `Reçu de paiement - ${receipt.course}`;
    const body = `Reçu Avalon Secure Academy\n\nCours : ${receipt.course}\nMontant : ${receipt.price}\nMoyen de paiement : ${receipt.method}\nDate : ${receipt.date}\n\nMerci pour votre confiance.`;
    const gmailUrl = `https://mail.google.com/mail/?view=cm&fs=1&to=${user?.email || ''}&su=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.open(gmailUrl, '_blank');
  };

  return (
    <div className="fixed inset-0 bg-[#0A0E1A]/90 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-slate-900/90 border border-slate-800 rounded-2xl p-7 w-full max-w-sm relative">
        <button onClick={onClose} className="absolute top-4 right-4 text-slate-500 hover:text-white text-sm transition-colors">
          ✕
        </button>

        {!isAuthenticated ? (
          <div className="text-center py-6">
            <p className="text-slate-300 text-sm mb-5">Connecte-toi d'abord pour débloquer ce cours.</p>
            <Link
              to="/login"
              onClick={onClose}
              className="inline-block bg-blue-600 hover:bg-blue-500 text-white font-semibold px-6 py-3 rounded-lg text-sm transition-colors"
            >
              Se connecter
            </Link>
          </div>
        ) : !success ? (
          <>
            <h2 className="text-white font-bold text-lg mb-1">{course.title}</h2>
            <p className="text-blue-400 font-bold text-xl mb-6">
              {course.is_free ? 'Gratuit' : `${course.price.toLocaleString()} FCFA`}
            </p>

            {error && (
              <div className="bg-red-500/10 border border-red-500/30 text-red-400 text-xs rounded-lg px-3 py-2 mb-4">
                {error}
              </div>
            )}

            <form onSubmit={handlePayment} className="space-y-5">
              <div className="grid grid-cols-2 gap-3">
                {methods.map((m) => (
                  <button
                    key={m.key}
                    type="button"
                    onClick={() => setMethod(m.key)}
                    className={`p-3 rounded-lg border flex flex-col items-center gap-2 transition-colors ${
                      method === m.key
                        ? 'border-blue-500 bg-blue-500/10'
                        : 'border-slate-700 hover:border-slate-500'
                    }`}
                  >
                    {m.logo_url ? (
                      <img src={m.logo_url} alt={m.display_name} className="h-6 object-contain" />
                    ) : (
                      <span className="text-xs font-bold uppercase text-slate-300">{m.key}</span>
                    )}
                    <span className={`text-[10px] font-semibold uppercase ${method === m.key ? 'text-blue-400' : 'text-slate-500'}`}>
                      {m.display_name}
                    </span>
                  </button>
                ))}
              </div>

              <button
                type="submit"
                disabled={!method || processing}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 disabled:text-slate-600 text-white font-semibold py-3 rounded-lg text-sm transition-colors"
              >
                {processing ? 'Traitement en cours...' : 'Confirmer le paiement'}
              </button>
            </form>
          </>
        ) : (
          <div className="py-2">
            <div className="text-center mb-6">
              <div className="w-14 h-14 rounded-full bg-emerald-500/10 border border-emerald-500/30 flex items-center justify-center text-emerald-400 text-2xl mx-auto mb-4">✓</div>
              <h3 className="text-white font-bold mb-1">Accès débloqué</h3>
              <p className="text-slate-400 text-sm">Le module est maintenant disponible dans ton espace.</p>
            </div>

            <div className="bg-slate-950 border border-slate-800 rounded-lg p-4 text-xs space-y-2 mb-5">
              <div className="flex justify-between"><span className="text-slate-500">Cours</span><span className="text-slate-200">{receipt.course}</span></div>
              <div className="flex justify-between"><span className="text-slate-500">Montant</span><span className="text-slate-200">{receipt.price}</span></div>
              <div className="flex justify-between"><span className="text-slate-500">Moyen</span><span className="text-slate-200">{receipt.method}</span></div>
              <div className="flex justify-between"><span className="text-slate-500">Date</span><span className="text-slate-200">{receipt.date}</span></div>
            </div>

            <div className="space-y-2">
              <button onClick={sendReceiptByEmail} className="w-full bg-white hover:bg-slate-100 text-slate-900 font-semibold py-3 rounded-lg text-sm transition-colors">
                Envoyer le reçu par email
              </button>
              <button onClick={onClose} className="w-full bg-slate-800 hover:bg-slate-700 text-white font-semibold py-3 rounded-lg text-sm transition-colors">
                Fermer
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};
export default PaymentModal;
